using System;
using System.IO;
using System.Linq;
using System.Windows;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewGvgScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual)VerifyGvgUi(folder);if(VerificationRun.Network)VerifyGvgTcp(folder);var cards=catalog.Deckable(catalog.Pool(GvgRules.SetId)).Select(c=>new{Id=c.Id,Name=c.Name,SetId=c.SetId,Supported=matchRules.Supports(c)}).ToArray();JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=cards.Count(c=>c.Supported),TotalCards=cards.Length,NewNeutralSupported=cards.Count(c=>c.SetId==GvgRules.SetId&&c.Supported),Cards=cards});File.WriteAllText(Path.Combine(folder,"gvg-verification.txt"),"PASS: "+(checks-before)+" assertions; WPF="+VerificationRun.Visual+"; loopback TCP="+VerificationRun.Network+". GvG filtering, fixed-size boards, generated hand privacy, secrets, cost auras, deathrattles and Mega Windfury. No physical mouse or two-PC test.");}
 void VerifyGvgUi(string folder){LeaveLan();draft=new DeckDocument{PoolId=GvgRules.SetId,ClassId="MAGE"};SyncDeckControls();RefreshVersionPicker();classFilterPicker.SelectedIndex=0;typePicker.SelectedIndex=0;costPicker.SelectedIndex=0;searchBox.Text="";versionPicker.SelectedItem=versionPicker.Items.Cast<Choice>().Single(c=>c.Key==GvgRules.SetId);ShowPage("deck");RefreshDeck();Check(filteredCards.Count==51&&filteredCards.All(matchRules.Supports),"GvG version filter shows all 51 available neutral cards");searchBox.Text="机械跃迁者";Check(filteredCards.Count==1&&filteredCards[0].Cost==2,"Search finds original two-mana Mechwarper");ShowDeckCard(filteredCards[0]);Check(cardInfo.Text.Contains("可对战")&&!cardInfo.Text.Contains("暂不可用"),"New card details reflect actual implemented support");ApplyTheme(true,true);ApplyMode(false);Render(Path.Combine(folder,"gvg-builder-normal.png"));ApplyMode(true);Render(Path.Combine(folder,"gvg-builder-minimal.png"));Check(Width==392&&Height==300,"GvG builder retains fixed minimal size");ApplyMode(false);searchBox.Text="";versionPicker.SelectedIndex=0;
  localTest=true;match=MatchFixture();match.CardPoolId=GvgRules.SetId;foreach(var p in match.Players){p.Board.Clear();p.Hand.Clear();}matchViewSeat=0;awaitHandoff=false;foreach(string id in new[]{"GVG_110","GVG_110t","GVG_111t","GVG_113","GVG_106","GVG_006","GVG_095"})match.Summon(0,id);foreach(string id in new[]{"GVG_096","GVG_105","GVG_114","GVG_091","GVG_085","GVG_103","GVG_044"})match.Summon(1,id);ShowPage("match");SetEffectsLevel(EffectLevel.Low);RenderMatch();UpdateLayout();Check(UnitTags(match.Players[1].Board[3]).Contains("扰魔"),"Nullifier displays its spell and hero-power targeting protection");Check(UnitTags(match.Players[0].Board[2]).Contains("超级风怒"),"V-07-TR-0N displays explicit Mega Windfury keyword");Check(match.Players.All(p=>p.Board.Count==7)&&Width==548&&Height==474,"Two complete GvG boards fit normal fixed window");Render(Path.Combine(folder,"gvg-battle-normal.png"));ApplyMode(true);RenderMatch();Check(matchEffectsCanvas.Visibility==Visibility.Collapsed,"Minimal GvG board hides all effects");Render(Path.Combine(folder,"gvg-battle-minimal.png"));ApplyMode(false);localTest=false;match=null;
 }
 void VerifyGvgTcp(string folder){LeaveLan();ApplyTheme(true,true);ApplyMode(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{
  lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedIndex=0;lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanModePicker.SelectedIndex=0;guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"GvG peers connect using runtime-promoted old decks");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"GvG host mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"GvG guest mulligan");var g=lanAuthority.Game;Check(g.CardPoolId==GvgRules.SetId&&guest.match.CardPoolId==GvgRules.SetId,"Match pool identity reaches guest explicitly");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=p.MaxMana=10;p.Health=30;}g.Active=0;int master=NaxxUiHand(g,"GVG_110");PublishLan();BeginCard(master);ClickEmptySlot(0,0);PumpLan(()=>!lanWaiting&&guest.match.Players[0].Board.Count==3,"Boom battlecry reaches guest with both Bots");Check(guest.match.Players[0].Board.Select(u=>u.CardId).SequenceEqual(new[]{"GVG_110t","GVG_110","GVG_110t"}),"Both clients preserve Boom left and right placement");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.Summon(0,"GVG_006");int mech=NaxxUiHand(g,"GVG_044",1);g.Summon(1,"GVG_006");PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==mech),"Guest receives own Mech and cost aura");Check(guest.match.HandCost(1,guest.match.Players[1].Hand.Single(h=>h.Id==mech))==2&&LanProtocol.View(g,0,"gvg-private",1).Players[1].Hand.Length==0,"Cost aura matches authority without revealing hand to opponent");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.DestroySecrets(0);g.DestroySecrets(1);g.ArmSecret(1,new HandCard{Id=971900,CardId="VAN_EX1_287"});int kezan=NaxxUiHand(g,"GVG_074");PublishLan();BeginCard(kezan);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[0].SecretCount==1&&guest.match.Players[1].SecretCount==0,"Kezan transferred secret count reaches both sides");Check(secretNoticeText!=null&&secretNoticeText.Contains("科赞秘术师夺取奥秘"),"Secret owner notice names Kezan rather than Scientist");Check(guest.match.SecretCards(1).Length==0&&match.SecretCards(0).Single()=="VAN_EX1_287","Kezan privately transfers secret identity to new owner only");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.DestroySecrets(0);g.Summon(1,"GVG_082");var first=g.Players[1].Board.Single();int missile=NaxxUiHand(g,"VAN_CS2_024");PublishLan();BeginCard(missile);ClickMatchTarget(new MatchTarget(1,first.Id));PumpLan(()=>guest.match.Players[1].HandCount==1&&guest.match.Players[1].Hand.Count==1&&GvgRules.Parts.Contains(guest.match.Players[1].Hand[0].CardId),"Clockwork Gnome Part privately reaches guest");Check(LanProtocol.View(g,0,"gvg-private",1).Players[1].Hand.Length==0&&g.Players[1].Hand.Single().Generated,"Host view never obtains opponent's Part identity");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}var giant=g.Summon(0,"GVG_111t");g.Players[1].Health=100;PublishLan();for(int n=0;n<4;n++){ClickMatchTarget(new MatchTarget(0,giant.Id));ClickMatchTarget(new MatchTarget(1));int expected=n+1;PumpLan(()=>guest.match.Players[0].Board.Count==1&&guest.match.Players[0].Board.Single().AttacksUsed==expected,"Mega Windfury attack synchronizes");}Check(g.Players[1].Health==84&&guest.match.Players[1].Health==84&&g.CanAttack(0,giant)!=null,"Both clients agree on four attacks and exhausted state");
  Render(Path.Combine(folder,"gvg-lan-voltron.png"));
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
}
